"""Contact sheet rows for substitute teachers."""
import typing

import rosterkit.errors
def _cells(student: rosterkit.models.Student) -> typing.Tuple[str, str, str]:
    if not student.email:
        raise rosterkit.errors.ProjectError(
            f"no email for student: {student.display_name}"
        )
    return (student.display_name, student.section, student.email)
def contact_rows(students: typing.Iterable[rosterkit.models.Student]) -> typing.List[str]:
    """Text rows sorted by name with name, section and email in columns."""
    ordered = sorted(students, key=lambda s: s.display_name)
    if not ordered:
        raise rosterkit.errors.ProjectError("no students for the contact sheet")
    table = [_cells(student) for student in ordered]
    widths = [max(len(row[i]) for row in table) for i in range(3)]
    return [
        "  ".join(cell.ljust(w) for cell, w in zip(row, widths)).rstrip()
        for row in table
    ]
# end of file
