import unittest

import rosterkit.models
import rosterkit.errors
import rosterkit.contacts
def make(last, first, section, email):
    return rosterkit.models.Student("1", last, first, section, email)
class ContactRowsTests(unittest.TestCase):
    def setUp(self):
        self.rows = rosterkit.contacts.contact_rows([
            make("Zed", "Amy", "B", "amy@x.org"),
            make("Adams", "Bo", "A", "bo@x.org")
        ])

    def test_rows_are_sorted_by_name(self):
        self.assertTrue(self.rows[0].startswith("Adams, Bo"))

    def test_row_count(self):
        self.assertEqual(len(self.rows), 2)

    def test_columns_line_up(self):
        self.assertEqual(self.rows[0].index("A  "), self.rows[1].index("B  "))

    def test_row_has_email(self):
        self.assertTrue(self.rows[1].endswith("amy@x.org"))

    def test_missing_email_names_student(self):
        with self.assertRaisesRegex(rosterkit.errors.ProjectError, "Kim, Lee"):
            rosterkit.contacts.contact_rows([make("Kim", "Lee", "A", None)])

    def test_empty_list_raises(self):
        with self.assertRaises(rosterkit.errors.ProjectError):
            rosterkit.contacts.contact_rows([])
# end of file
